DEBUG = 0

class CacheEntry(object):

	def __init__(self, f, d, n, a_f, a_d, a_n, excluded=None):
		self.f = f
		self.d = d
		self.n = n
		self.a_f = a_f
		self.a_d = a_d
		self.a_n = a_n
		self.excluded = excluded

	def complete(self, prev):
		return self.excluded is None or self.excluded == prev

	def furthest(self, prev):
		if self.excluded is None:
			if prev == self.n:
				return (self.a_f, self.a_d)
			else:
				return (self.f, self.d)
		elif self.excluded == prev:
			return (self.f, self.d)
		else:
			raise Exception('Failed')

	def update(self, f, d, n):
		if d > self.d:
			if n != self.n:
				(self.a_f, self.a_d, self.a_n) = (self.f, self.d, self.n)
			(self.f, self.d, self.n) = (f, d, n)
		elif d > self.a_d and n != self.n:
			(self.a_f, self.a_d, self.a_n) = (f, d, n)
		if n == self.excluded:
			self.excluded = None

	def __str__(self):
		return ' '.join(map(str, [self.f, self.d, self.n, self.a_f, self.a_d, self.a_n, self.excluded]))

class Cache(object):

	def __init__(self, tree):
		self.tree = tree
		self.data = dict()

	def finish(self, node, prev):
		missing = self.data[node].excluded
		if missing not in self.data or not self.data[missing].complete(node):
			return (False, [(missing, node)])
		else:
			(f, d) = self.data[missing].furthest(node)
			self.data[node].update(f, d + 1, missing)
			return (True, self.data[node].furthest(prev))

	def construct(self, node, prev):
		c = CacheEntry(node, 0, node, 0, 0, 0, excluded=prev)
		for child in self.tree[node]:
			if child == prev:
				continue
			(f, d) = self.data[child].furthest(node)
			c.update(f, d + 1, child)
		return c

	def furthest(self, node, prev=None):
		if node in self.data:
			if self.data[node].complete(prev):
				return (True, self.data[node].furthest(prev))
			else:
				return self.finish(node, prev)
		else:
			req = [(child, node) for child in self.tree[node] if child != prev and (child not in self.data or not self.data[child].complete(node))]
			if req:
				return (False, req)
			self.data[node] = self.construct(node, prev)
			return (True, self.data[node].furthest(prev))

	def __str__(self):
		return '\n'.join(('{}--- {}'.format(key, str(self.data[key])) for key in sorted(self.data.keys())))

def longest_f(tree):
	cache = Cache(tree)

	def longest(origin):
		(ok, ret) = cache.furthest(origin)
		if DEBUG > 1:
			print('Finding longest from', origin)
			print('Called furthest origin')
			print('origin:', origin)
			print('ok, ret:', ok, ret)
			if ok:
				print(cache.data[origin])
			print('--------------------')
		if ok:
			return ret
		original_origin = origin
		stack = ret
		while stack:
			(origin, prev) = stack[-1]
			(ok, ret) = cache.furthest(origin, prev)
			if DEBUG > 1:
				print('Called furthest_prev')
				print('origin:', origin)
				print('prev:', prev)
				print('ok, ret:', ok, ret)
				if ok:
					print(cache.data[origin])
				print('--------------------')
			if ok:
				stack.pop()
			else:
				stack += ret
		(ok, ret) = cache.furthest(original_origin)
		if DEBUG > 1:
			print('Called furthest origin')
			print('original_origin:', original_origin)
			print('ok, ret:', ok, ret)
			if ok:
				print(cache.data[original_origin])
			print('--------------------')
		if not ok:
			raise Exception('Failed to find all necessary information')
			print(ret)
		return ret

	def print_cache():
		print(cache)
	return (longest, print_cache)

def distance(longest_f, v, k):
	ki = 0
	journeys = []
	distance = 0
	while ki < k:
		(v, d) = longest_f(v)
		journeys.append(d)
		distance += d
		ki += 1
		if len(journeys) >= 3 and all((journey == journeys[-1] for journey in journeys[-3:])):
			distance += (k - ki) * journeys[-1]
			if DEBUG:
				print('Skipping from journeys {} to total_distance of {}'.format(journeys, distance))
			break
	return distance

